nextflow_process {

    name "Test Process HUMANN3_REGROUP"
    script "../main.nf"
    process "HUMANN3_REGROUP"
    tag "modules"
    tag "modules_nfcore"
    tag "humann3"
    tag "humann3/regroup"

    test("humann3_regroup - tsv") {
        def utility_db
        setup {
            utility_db = extract('https://raw.githubusercontent.com/nf-core/test-datasets/funcprofiler/data/database/humann/v3/utility_nfDEMO.tar.gz')
        }

        when {
            process {
                """
                input[0] = channel.of([
                    [ id:'test', single_end:false ], // meta map
                    file( params.modules_testdata_base_path + 'genomics/prokaryotes/metagenome/biobakery/test_genefamilies.tsv', checkIfExists: true )
                ])
                input[1] = "uniref90_level4ec"
                input[2] = file('${utility_db}')
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("humann3_regroup - tsv - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = channel.of([
                    [ id:'test', single_end:false ], // meta map
                    file( params.modules_testdata_base_path + 'genomics/prokaryotes/metagenome/biobakery/test_genefamilies.tsv', checkIfExists: true )
                ])
                input[1] = "uniref90_level4ec"
                input[2] = []
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

